<?php
/** Listado y visor de documentos normalizados; nunca recibe rutas físicas. */
$documents = is_array($digitalRecord['documents'] ?? null) ? $digitalRecord['documents'] : [];
$recordIsProject = (string) ($digitalRecord['entity']['type'] ?? '') === 'project';
$recordFileOwner = $recordIsProject ? 'proyecto' : 'material';
$archives = is_array($digitalRecord['archives'] ?? null) ? $digitalRecord['archives'] : [];
$package = is_array($digitalRecord['package'] ?? null) ? $digitalRecord['package'] : [];
$canManageFiles = !empty($digitalRecord['can_manage_files']) && !empty($digitalRecord['file_upload']);
$canDownloadFiles = !empty($digitalRecord['capabilities']['download_files']);
$restorableFiles = is_array($digitalRecord['restorable_files'] ?? null) ? $digitalRecord['restorable_files'] : [];
$globalFileActions = is_array($digitalRecord['global_file_actions'] ?? null) ? $digitalRecord['global_file_actions'] : [];
$documentReview = is_array($digitalRecord['document_review'] ?? null) ? $digitalRecord['document_review'] : [];
$documentReviewEnabled = $recordIsProject
    && (string)($digitalRecord['context'] ?? '') === 'academic_management'
    && (string)($digitalRecord['admin_actions']['status'] ?? '') === 'development'
    && $documentReview !== [];
$documentReviewSummary = is_array($documentReview['summary'] ?? null) ? $documentReview['summary'] : [];
$fileExtension = static function (array $file): string {
    $extension = trim((string) ($file['extension'] ?? ''));
    if ($extension === '') {
        $extension = pathinfo((string) ($file['name'] ?? ''), PATHINFO_EXTENSION);
    }
    return mb_strtolower(ltrim($extension, '.'), 'UTF-8');
};
$regularFiles = [];
$zipFiles = [];
$seenFileIds = [];
foreach (array_merge($documents, $archives) as $file) {
    $fileId = (int) ($file['id'] ?? 0);
    if ($fileId > 0 && isset($seenFileIds[$fileId])) {
        continue;
    }
    if ($fileId > 0) {
        $seenFileIds[$fileId] = true;
    }
    if ($fileExtension($file) === 'zip') {
        $zipFiles[] = $file;
    } else {
        $regularFiles[] = $file;
    }
}
$fileNameKey = static fn (array $file): string => mb_strtolower(trim((string) ($file['name'] ?? '')), 'UTF-8');
$sortFilesByName = static function (array $items) use ($fileNameKey): array {
    $indexedItems = [];
    foreach (array_values($items) as $index => $file) {
        $indexedItems[] = ['file' => $file, 'index' => $index];
    }
    usort($indexedItems, static function (array $left, array $right) use ($fileNameKey): int {
        $comparison = strnatcmp($fileNameKey($left['file']), $fileNameKey($right['file']));
        return $comparison !== 0 ? $comparison : ($left['index'] <=> $right['index']);
    });
    return array_map(static fn (array $item): array => $item['file'], $indexedItems);
};
$documents = $sortFilesByName($regularFiles);
$archives = $sortFilesByName($zipFiles);
$selectableFiles = array_values(array_merge($documents, $archives));
$totalZipSizeBytes = array_sum(array_map(static fn (array $file): int => (int) ($file['size_bytes'] ?? 0), $selectableFiles));
$totalZipSizeLabel = !empty($package['size']) ? (string) $package['size'] : ($totalZipSizeBytes > 0 ? ArchiveService::formatBytes($totalZipSizeBytes) : '');
$retirableFiles = array_values(array_filter($selectableFiles, static fn (array $file): bool => empty($file['is_package'])));
$selectedDocument = current(array_filter(
    $selectableFiles,
    static fn (array $file): bool => !empty($file['is_presentation'])
        && (!array_key_exists('available', $file) || !empty($file['available']))
)) ?: null;
$archiveGroupLabel = 'Archivos ZIP';
$documentGroups = array_filter([
    'Archivos' => array_values(array_filter($documents, static fn (array $document): bool => empty($document['is_package']))),
    $archiveGroupLabel => $archives,
]);
$visualForExtension = static function (string $extension): array {
    $normalized = mb_strtolower(ltrim(trim($extension), '.'), 'UTF-8');
    return match ($normalized) {
        'pdf' => ['icon' => 'fa-file-lines', 'label' => 'PDF'],
        'doc', 'docx', 'odt', 'rtf' => ['icon' => 'fa-file-word', 'label' => mb_strtoupper($normalized, 'UTF-8')],
        'xls', 'xlsx', 'csv', 'ods' => ['icon' => 'fa-file-excel', 'label' => mb_strtoupper($normalized, 'UTF-8')],
        'ppt', 'pptx', 'odp' => ['icon' => 'fa-file-powerpoint', 'label' => mb_strtoupper($normalized, 'UTF-8')],
        'zip', 'rar', '7z', 'tar', 'gz' => ['icon' => 'fa-file-zipper', 'label' => mb_strtoupper($normalized, 'UTF-8')],
        'png', 'jpg', 'jpeg', 'webp', 'gif', 'svg' => ['icon' => 'fa-file-image', 'label' => mb_strtoupper($normalized, 'UTF-8')],
        'txt', 'md' => ['icon' => 'fa-file-lines', 'label' => mb_strtoupper($normalized, 'UTF-8')],
        default => ['icon' => 'fa-file', 'label' => 'FILE'],
    };
};
